import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 7100;
    static final long INF = 1000000000L;

    static class Edge {
        int from, to;
        long flow, capacity;
        public Edge(int from, int to, long flow, long capacity) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class FlowSolver {
        List<Edge> edges = new ArrayList<>();
        List<Integer>[] adj = new ArrayList[MAX_SIZE];
        int s, t;
        int[] dist = new int[MAX_SIZE];
        int[] visited = new int[MAX_SIZE];
        int[] current = new int[MAX_SIZE];

        public FlowSolver() {
            for (int i = 0; i < MAX_SIZE; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        void reset() {
            edges.clear();
            for (int i = 0; i < MAX_SIZE; i++) {
                adj[i].clear();
            }
        }

        void addEdge(int u, int v, long cap) {
            Edge e1 = new Edge(u, v, 0L, cap);
            Edge e2 = new Edge(v, u, 0L, 0);
            edges.add(e1);
            edges.add(e2);
            adj[u].add(edges.size() - 2);
            adj[v].add(edges.size() - 1);
        }

        boolean buildLevelGraph() {
            Arrays.fill(visited, 0);
            Arrays.fill(dist, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            dist[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int i : adj[v]) {
                    Edge e = edges.get(i);
                    int u = e.to;
                    if (visited[u] == 0 && e.capacity > e.flow) {
                        dist[u] = dist[v] + 1;
                        q.offer(u);
                        visited[u] = 1;
                    }
                }
            }
            return visited[t] == 1;
        }

        long sendFlow(int v, long flow) {
            if (v == t || flow == 0) return flow;
            long total = 0;
            for (int i = current[v]; i < adj[v].size(); i++) {
                int idx = adj[v].get(i);
                Edge e = edges.get(idx);
                if (dist[v] + 1 == dist[e.to]) {
                    long pushed = sendFlow(e.to, Math.min(flow, e.capacity - e.flow));
                    if (pushed > 0) {
                        e.flow += pushed;
                        edges.get(idx ^ 1).flow -= pushed;
                        total += pushed;
                        flow -= pushed;
                        if (flow == 0) break;
                    }
                }
            }
            return total;
        }

        long maxFlow() {
            long totalFlow = 0;
            while (buildLevelGraph()) {
                Arrays.fill(current, 0);
                totalFlow += sendFlow(s, INF);
            }
            return totalFlow;
        }
    }

    static char[][] mazeA = new char[14][14];
    static char[][] mazeB = new char[14][14];
    static boolean[][] visitedMap = new boolean[14][14];
    static int[][] distMap = new int[14][14];
    static int sizeN;
    static int[] targetNodes = new int[103];

    static int[] dx = {1, 0, 0, -1};
    static int[] dy = {0, 1, -1, 0};

    static void BFS(int x, int y) {
        for (int i = 0; i < 14; i++) {
            Arrays.fill(distMap[i], 111);
            Arrays.fill(visitedMap[i], false);
        }
        distMap[x][y] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{x, y});
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], d = distMap[cx][cy];
            if (visitedMap[cx][cy]) continue;
            visitedMap[cx][cy] = true;
            for (int i = 0; i < 4; i++) {
                int tx = cx + dx[i], ty = cy + dy[i];
                if (tx <= 0 || tx > sizeN || ty <= 0 || ty > sizeN || visitedMap[tx][ty] || mazeA[tx][ty] == 'Y') continue;
                distMap[tx][ty] = d + 1;
                q.offer(new int[]{tx, ty});
            }
        }
    }

    static int get_idx(int level, int x, int y) {
        return level * sizeN * sizeN + (x - 1) * sizeN + y;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        sizeN = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= sizeN; i++) {
            String line = br.readLine();
            mazeA[i] = (' ' + line).toCharArray();
        }
        for (int i = 1; i <= sizeN; i++) {
            String line = br.readLine();
            mazeB[i] = (' ' + line).toCharArray();
        }
        FlowSolver solver = new FlowSolver();
        solver.s = 0;
        solver.t = MAX_SIZE - 2;
        int zx = 0, zy = 0;
        outer:
        for (int i = 1; i <= sizeN; i++) {
            for (int j = 1; j <= sizeN; j++) {
                if (mazeA[i][j] == 'Z') {
                    zx = i;
                    zy = j;
                    break outer;
                }
            }
        }
        for (int i = 1; i <= sizeN * sizeN; i++) {
            targetNodes[i] = MAX_SIZE - 3 - (sizeN * sizeN - i);
        }
        BFS(zx, zy);
        for (int i = 1; i <= sizeN; i++) {
            for (int j = 1; j <= sizeN; j++) {
                if (mazeA[i][j] >= '0' && mazeA[i][j] <= '9')
                    solver.addEdge(solver.s, get_idx(0, i, j), mazeA[i][j] - '0');
                if (mazeB[i][j] >= '0' && mazeB[i][j] <= '9')
                    solver.addEdge(targetNodes[get_idx(0, i, j)], solver.t, mazeB[i][j] - '0');
                solver.addEdge(get_idx(0, i, j), targetNodes[get_idx(0, i, j)], INF);
            }
        }
        for (int i = 1; i <= t; i++) {
            for (int j = 1; j <= sizeN; j++) {
                for (int k = 1; k <= sizeN; k++) {
                    if (mazeA[j][k] == 'Y' || mazeA[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = j + dx[l], ty = k + dy[l];
                        if (tx >= 1 && tx <= sizeN && ty >= 1 && ty <= sizeN && mazeA[tx][ty] != 'Y' && mazeA[tx][ty] != 'Z') {
                            if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                                solver.addEdge(get_idx(i - 1, tx, ty), get_idx(i, j, k), INF);
                            }
                        }
                    }
                    solver.addEdge(get_idx(i, j, k), targetNodes[get_idx(0, j, k)], INF);
                }
            }
        }
        System.out.println(solver.maxFlow());
    }
}

